--
-- Name: food_metrics_100g; Type: VIEW; Schema: digestmess; Owner: sharie
--

CREATE VIEW digestmess.food_metrics_100g AS
 SELECT f."Cn code",
    f."Descriptor",
    protein."Nutrient value" AS protein_g_per_100g,
    fat."Nutrient value" AS fat_g_per_100g,
    vitc."Nutrient value" AS vitamin_c_mg_per_100g
   FROM (((digestmess.fdes f
     LEFT JOIN digestmess.nutval protein ON (((protein."Cn Code" = f."Cn code") AND (protein."Nutrient code" = 203))))
     LEFT JOIN digestmess.nutval fat ON (((fat."Cn Code" = f."Cn code") AND (fat."Nutrient code" = 204))))
     LEFT JOIN digestmess.nutval vitc ON (((vitc."Cn Code" = f."Cn code") AND (vitc."Nutrient code" = 401))));


