--
-- Name: food_metrics_per_serving; Type: VIEW; Schema: digestmess; Owner: sharie
--

CREATE VIEW digestmess.food_metrics_per_serving AS
 SELECT fm."Cn code",
    fm."Descriptor",
    (w."Unit amount")::numeric AS grams_per_serving,
    round((((fm.protein_g_per_100g * w."Unit amount") / (100.0)::double precision))::numeric, 2) AS protein_g_per_serving,
    round((((fm.fat_g_per_100g * w."Unit amount") / (100.0)::double precision))::numeric, 2) AS fat_g_per_serving,
    round((((fm.vitamin_c_mg_per_100g * w."Unit amount") / (100.0)::double precision))::numeric, 2) AS vitamin_c_mg_per_serving
   FROM (digestmess.food_metrics_100g fm
     JOIN digestmess.wght w ON (((w."Cn code" = fm."Cn code") AND (w."Sequence num" = 1))));


